corrected_code:
import { Context } from '@temporalio/activity';
import { db } from '../lib/database';
import { stripeClient } from '../lib/stripe';

export async function applyTenantTierUpgradeActivity(input: {
  tenantId: string;
  newPlanTier: string;
  maxSeats: number;
  paymentIntentId: string;
}): Promise<{ upgraded: boolean }> {
  const { tenantId, newPlanTier, maxSeats, paymentIntentId } = input;

  const payment = await stripeClient.paymentIntents.retrieve(paymentIntentId);
  if (payment.status !== 'succeeded' || payment.metadata.tenantId !== tenantId) {
    throw new Error('Upgrade rejected: valid payment confirmation required for tenant');
  }

  const updateResult = await db('tenant_subscriptions')
    .where({ tenant_id: tenantId })
    .update({
      plan_tier: newPlanTier,
      seat_allocation: maxSeats,
      upgraded_at: new Date()
    });

  return { upgraded: updateResult > 0 };
}
